const form=document.querySelector('form');document.querySelectorAll('[data-register]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelector('#header-nav-items-dropdown')?.style.setProperty('right','-100%');form.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
const menu=document.querySelector('#mob-menu-btn');menu?.setAttribute('aria-label','Open navigation');menu?.addEventListener('click',()=>{const n=document.querySelector('#header-nav-items-dropdown');if(n){n.style.right='0';menu.setAttribute('aria-expanded','true')}});document.querySelectorAll('#header-nav-items-dropdown *').forEach(n=>{if(n.textContent.trim()==='X')n.addEventListener('click',()=>{document.querySelector('#header-nav-items-dropdown').style.right='-100%';menu?.setAttribute('aria-expanded','false')})});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#header-nav-items-dropdown')?.style.setProperty('right','-100%');menu?.setAttribute('aria-expanded','false')}});
document.querySelectorAll('button').forEach(b=>{if(b.textContent.trim()==='▲')b.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}))});
form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);const lines=[`Hello Team Arora,`,'','Please send me the latest available information about Navera at Mayfield Village.','',`Name: ${d.get('firstName')} ${d.get('lastName')}`,`Email: ${d.get('email')}`,`Phone: ${d.get('phone')}`,`Realtor: ${d.get('isAgent')==='1'?'Yes':'No'}`];form.querySelectorAll('select').forEach(s=>{const label=s.parentElement.querySelector('label')?.textContent.trim()||s.getAttribute('aria-label')||'Preference';lines.push(`${label}: ${s.options[s.selectedIndex]?.text}`)});lines.push('',`Email consent: ${d.get('consent')?'Yes':'No'}`,`SMS consent: ${d.get('smsConsent')?'Yes':'No'}`);location.href='mailto:parveen@teamarora.com?subject='+encodeURIComponent('Navera at Mayfield Village enquiry')+'&body='+encodeURIComponent(lines.join('\n'));document.querySelector('#form-status').textContent='Send the prepared message from your email app to complete your request. If your email app does not open, contact parveen@teamarora.com or call 416-910-8923.'});
(async()=>{const container=document.querySelector('#map');if(!container)return;try{const r=await fetch('/assets/map-data.json');if(!r.ok)throw new Error('Map data unavailable');const d=await r.json();if(!window.maplibregl)throw new Error('Map unavailable');const map=new maplibregl.Map({container,center:d.center,zoom:15,style:{version:8,sources:{basemap:{type:'raster',tiles:['https://basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors © CARTO'}},layers:[{id:'basemap',type:'raster',source:'basemap'}]},scrollZoom:false});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'bottom-right');const pin=document.createElement('div');pin.className='replica-pin';pin.style.backgroundImage=`url('${d.logo}')`;new maplibregl.Marker({element:pin}).setLngLat(d.center).setPopup(new maplibregl.Popup().setText('Navera at Mayfield Village — builder-supplied community reference')).addTo(map);let markers=[];const categories=[...document.querySelectorAll('.cat-display [role=button]')];categories.forEach((button,i)=>{const activate=()=>{const selected=button.getAttribute('aria-pressed')!=='true';categories.forEach(b=>b.setAttribute('aria-pressed','false'));markers.forEach(m=>m.remove());markers=[];if(!selected){map.flyTo({center:d.center,zoom:15});return}button.setAttribute('aria-pressed','true');const category=d.categories[i];const items=d.markers.filter(m=>m.categoryId===category.id);const bounds=new maplibregl.LngLatBounds(d.center,d.center);items.forEach(m=>{const el=document.createElement('button');el.type='button';el.className='map-marker';el.setAttribute('aria-label',m.name);const content=document.createElement('div');const strong=document.createElement('strong');strong.textContent=m.name;content.append(strong);if(m.address){const p=document.createElement('p');p.textContent=m.address;content.append(p)}const a=document.createElement('a');a.textContent='Open in Google Maps ↗';a.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(m.name+' Brampton');a.target='_blank';a.rel='noopener';content.append(a);const position=[m.location.lng,m.location.lat];markers.push(new maplibregl.Marker({element:el}).setLngLat(position).setPopup(new maplibregl.Popup({offset:12}).setDOMContent(content)).addTo(map));bounds.extend(position)});if(items.length)map.fitBounds(bounds,{padding:50,maxZoom:14,duration:500})};button.addEventListener('click',activate);button.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}})});window.addEventListener('resize',()=>map.resize());}catch(e){container.innerHTML='<div class="replica-map-error">Explore the Navera community at Countryside Drive & Torbram Road.<br><a href="https://www.google.com/maps/search/?api=1&query=Countryside+Drive+and+Torbram+Road+Brampton" target="_blank" rel="noopener">Open location in Google Maps ↗</a></div>'}})();
const actualMenu=document.querySelector('#header-nav-menu-icon-display button');actualMenu?.setAttribute('aria-label','Open navigation');actualMenu?.setAttribute('aria-expanded','false');actualMenu?.addEventListener('click',()=>{document.querySelector('#header-nav-items-dropdown').style.right='0';actualMenu.setAttribute('aria-expanded','true')});document.querySelector('#header-nav-x-icon-display')?.addEventListener('click',()=>{document.querySelector('#header-nav-items-dropdown').style.right='-100%';actualMenu?.setAttribute('aria-expanded','false')});const fixedNav=document.querySelector('.mobNav');const syncFixed=()=>fixedNav?.classList.toggle('replica-visible',scrollY>180);addEventListener('scroll',syncFixed,{passive:true});syncFixed();
